<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { wasWrong, latestAttempt, inPeriod, type StudentCourse } from '../student-pages';
const props=defineProps<{course:StudentCourse;focusQuestion?:string;initialFilter?:string}>();
const emit=defineEmits<{startAction:[text:string];openActivity:[id:string];backToStatus:[]}>();
const query=ref(''),source=ref(''),chapter=ref(''),kind=ref('all'),days=ref(0),selected=ref(''),pageNumber=ref(1);
watch(()=>props.focusQuestion,id=>{if(id)selected.value=id;},{immediate:true});
watch(()=>props.initialFilter,value=>{if(value){kind.value=value;selected.value='';}},{immediate:true});
const rows=computed(()=>props.course.questions.filter(q=>q.text.includes(query.value)&&(!source.value||q.source===source.value)&&(!chapter.value||q.chapterId===chapter.value)&&(!days.value||q.attempts.some(a=>inPeriod(a.at,days.value,props.course.asOf)))&&(kind.value==='all'||kind.value==='wrong'&&wasWrong(q)||kind.value==='unanswered'&&!q.attempts.length||kind.value==='pending'&&latestAttempt(q)?.result==='待判定')));
watch([query,source,chapter,kind,days],()=>pageNumber.value=1);
const question=computed(()=>props.course.questions.find(q=>q.id===selected.value));
function open(id:string){selected.value=id;}
function filter(value:string){kind.value=value;selected.value='';}
defineExpose({open,filter});
</script>
<template><div class="student-page question-records-page">
  <header class="page-header"><div><h2>题目记录</h2><p class="muted">{{course.title}}</p></div><span class="tiny">{{course.questions.length}} 道题 · {{course.questions.filter(wasWrong).length}} 道曾答错</span></header>
  <template v-if="!question"><div class="actions"><button :aria-pressed="kind==='all'" @click="kind='all'">全部题目</button><button :aria-pressed="kind==='wrong'" @click="kind='wrong'">错题</button><button :aria-pressed="kind==='unanswered'" @click="kind='unanswered'">未作答</button><button :aria-pressed="kind==='pending'" @click="kind='pending'">待判定</button></div><div class="controls"><label>查找题目<input v-model="query" type="search" placeholder="输入题目文字"/></label><label>章节<select aria-label="章节" v-model="chapter"><option value="">全部章节</option><option v-for="c in course.chapters" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>来源<select aria-label="来源" v-model="source"><option value="">全部来源</option><option>外部录入</option><option>讲解练习</option><option>检测</option></select></label><label>原作答日期<select aria-label="原作答日期" v-model.number="days"><option :value="0">全部（含未知日期）</option><option :value="7">近 7 天</option><option :value="30">近 30 天</option></select></label></div><p class="tiny">{{rows.length}} 道符合条件。同一道题保留历次作答，订正后仍可在错题中找到。</p>
    <section class="panel"><article v-for="q in rows.slice((pageNumber-1)*10,pageNumber*10)" :key="q.id" class="list-row"><div class="tags"><span class="badge">{{q.source}}</span><span v-if="wasWrong(q)" class="badge needs">曾答错</span><span class="tiny">{{course.chapters.find(c=>c.id===q.chapterId)?.name||'章节待确认'}}</span></div><button class="link question-text" @click="open(q.id)">{{q.text}}</button><div class="row"><p class="muted">{{latestAttempt(q)?'最近作答：'+latestAttempt(q)!.result+' · '+(latestAttempt(q)!.at||'原日期未知'):'未作答'}}{{q.note?' · '+q.note:''}}</p><button @click="open(q.id)">查看题目与作答</button></div></article><p v-if="!rows.length" class="empty">没有符合条件的题目。未作答、待判定的题目不计入错题。</p></section>
    <div v-if="rows.length>10" class="pagination"><button :disabled="pageNumber===1" @click="pageNumber--">上一页</button><span>第 {{pageNumber}} / {{Math.ceil(rows.length/10)}} 页</span><button :disabled="pageNumber*10>=rows.length" @click="pageNumber++">下一页</button></div>
  </template>
  <template v-else><div class="row back"><button @click="selected=''">← 返回题目列表</button><button v-if="focusQuestion" class="link" @click="emit('backToStatus')">返回判断依据 →</button></div><section class="panel"><div class="tags"><span class="badge">{{question.source}}</span><span v-if="wasWrong(question)" class="badge needs">曾答错</span><span class="tiny">{{course.chapters.find(c=>c.id===question?.chapterId)?.name||'章节待确认'}}</span></div><p class="question-text">{{question.text}}</p><svg v-if="question.figure==='length'" viewBox="0 0 500 130" role="img" aria-label="原长80米与新增原长四分之一的题目图示" style="width:100%;max-width:520px"><rect x="20" y="20" width="320" height="44" fill="#d7eade" stroke="#438268"/><rect x="340" y="20" width="80" height="44" fill="#f5dfad" stroke="#ad8a40"/><text x="120" y="48" font-size="16">原长{{question.quantity||80}}米</text><text x="300" y="91" font-size="14">新增原长的1/4</text><text x="120" y="120" font-size="16">现在的总长是多少？</text></svg><p v-if="question.note" class="muted">{{question.note}}</p><div class="actions"><button class="primary" @click="emit('startAction','请讲解这道题：'+question.text)">讲讲这道题</button><button @click="emit('startAction','我想再试这道题，请结合已有作答决定是否原题复测或换题：'+question.text)">再试一次</button></div></section>
    <section class="panel"><h3>历次作答</h3><article v-for="a in question.attempts" :key="a.id" class="list-row"><div class="tags"><strong>{{a.result}}</strong><span class="badge">{{a.help}}</span><span class="tiny">{{a.at||'原作答日期未知'}}</span></div><p>原作答：{{a.answer}}</p><p class="muted">{{a.detail}}</p><p v-if="a.invalid" class="notice">本次依据已作废：{{a.invalid}}。原作答保留，不计入当前判断与统计。</p><button v-if="a.activityId&&course.activities.some(x=>x.id===a.activityId)" class="link" @click="emit('openActivity',a.activityId)">查看所属学习活动 →</button></article><p v-if="!question.attempts.length" class="empty">还没有作答记录。可以直接提问，不必先答错。</p></section>
  </template><p class="tiny">{{course.note}}</p>
</div></template>
